@extends('layouts.app') @section('title','Create invoice') @section('crumb','Billing') @section('content')<div class="page-heading"><div><p class="eyebrow">FINANCE</p><h1>Create invoice</h1><p class="muted">Add a service and record a full or partial payment.</p></div></div><form method="post" action="{{ route('billing.store') }}" class="panel form-panel">@csrf<div class="row g-3"><div class="col-md-6"><label class="form-label">Patient *</label><select class="form-select" name="patient_id" required><option value="">Choose patient</option>@foreach($patients as $p)<option value="{{ $p->id }}" @selected(old('patient_id',request('patient'))==$p->id)>{{ $p->name }} · {{ $p->patient_number }}</option>@endforeach</select></div><div class="col-md-6"><label class="form-label">Service</label><select class="form-select" name="service_id" id="service"><option value="">Custom service</option>@foreach($services as $s)<option value="{{ $s->id }}" data-price="{{ $s->price }}">{{ $s->name }} · ${{ number_format($s->price,2) }}</option>@endforeach</select></div><div class="col-md-6"><label class="form-label">Description *</label><input class="form-control" name="description" value="{{ old('description') }}" required></div><div class="col-md-2"><label class="form-label">Quantity *</label><input class="form-control" type="number" min="1" name="quantity" value="{{ old('quantity',1) }}" required></div><div class="col-md-4"><label class="form-label">Unit price ($) *</label><input class="form-control" type="number" min="0" step="0.01" name="unit_price" id="price" value="{{ old('unit_price',0) }}" required></div><div class="col-md-4"><label class="form-label">Discount ($)</label><input class="form-control" type="number" min="0" step="0.01" name="discount" value="{{ old('discount',0) }}"></div><div class="col-12"><hr><h2 class="form-subtitle">Initial payment <span class="optional">optional</span></h2></div><div class="col-md-6"><label class="form-label">Amount ($)</label><input class="form-control" type="number" min="0" step="0.01" name="payment_amount" value="{{ old('payment_amount',0) }}"></div><div class="col-md-6"><label class="form-label">Payment method</label><select class="form-select" name="method"><option>Cash</option><option>Card</option><option>Mobile Money</option></select></div></div><div class="form-actions"><a href="{{ route('billing.index') }}" class="btn btn-outline-secondary">Cancel</a><button class="btn btn-primary"><i class="bi bi-receipt me-2"></i>Create invoice</button></div></form>@endsection @push('scripts')<script>document.getElementById('service').addEventListener('change',e=>{const o=e.target.selectedOptions[0];if(o.dataset.price)document.getElementById('price').value=o.dataset.price;if(o.value&&!document.querySelector('[name=description]').value)document.querySelector('[name=description]').value=o.text.split(' · ')[0]})</script>@endpush
